<?phpinclude $_SERVER['DOCUMENT_ROOT'] . "/common/conf/config.inc.php";include $_SERVER['DOCUMENT_ROOT'] . "/module/board/board.lib.php";include $_SERVER['DOCUMENT_ROOT'] . "/module/shop/shop.lib.php";// DB연결$dblink = SetConn($_conf_db["main_db"]);$arrUserList = getBoardListBase("edu", "", "idx", $_REQUEST['mid'], 0, 0, $subQuery = "", $orderby = "");// 교육기간 및 총 교육 시간 계산$e_start_date = $arrUserList['list'][0]['e_start_date'];$e_end_date = $arrUserList['list'][0]['e_end_date'];$days = $arrUserList['list'][0]['days'];$start_hour = $arrUserList['list'][0]['start_hour'];$start_minute = $arrUserList['list'][0]['start_minute'];$end_hour = $arrUserList['list'][0]['end_hour'];$end_minute = $arrUserList['list'][0]['end_minute'];// Convert days to English for easier processing$days_map = [    '월' => 'Monday',    '화' => 'Tuesday',    '수' => 'Wednesday',    '목' => 'Thursday',    '금' => 'Friday',    '토' => 'Saturday',    '일' => 'Sunday'];$days_array = explode('|', $days);$days_of_week = array_map(function($day) use ($days_map) {    return $days_map[$day];}, $days_array);// Calculate total education period$start_date = new DateTime($e_start_date);$end_date = new DateTime($e_end_date);$interval = $start_date->diff($end_date);$total_days = $interval->days + 1; // Include the end date// Calculate total education hours$total_hours = 0;$current_date = clone $start_date;while ($current_date <= $end_date) {    if (in_array($current_date->format('l'), $days_of_week)) {        $total_hours += ($end_hour - $start_hour) + (($end_minute - $start_minute) / 60);    }    $current_date->modify('+1 day');}SetDisConn($dblink);echo $arrUserList['list'][0]['reception_status'] . "|" . $arrUserList['list'][0]['edu_no'] . "|" . $arrUserList['list'][0]['category1'] . "|" . $arrUserList['list'][0]['category2'] . "|" . $arrUserList['list'][0]['subject'] . "|" . $arrUserList['list'][0]['fee'] . "|" . $arrUserList['list'][0]['idx'] . "|" . $e_start_date . "|" . $e_end_date . "|" . $total_days . "|" . $total_hours ;?>